def object_pattern(keys):
    field=r'"(?:'+'|'.join(keys)+r')"\s*:\s*'+JS
    return r'\A\s*\{\s*'+field+r'(?:\s*,\s*'+field+r'){'+str(len(keys)-1)+r'}\s*\}\s*\z'

