def main():
    workflow=build();out=ROOT/'dist';out.mkdir(exist_ok=True)
    binary=plistlib.dumps(workflow,fmt=plistlib.FMT_BINARY,sort_keys=False)
    (out/'Translate-AI.unsigned.bplist').write_bytes(binary);(out/'Translate-AI.unsigned.shortcut').write_bytes(plistlib.dumps(workflow,sort_keys=False))
    report={'version':VERSION,'actions':len(workflow['WFWorkflowActions']),'binaryBytes':len(binary),'unsignedSHA256':hashlib.sha256(binary).hexdigest(),'nativeDeviceVerified':False}
    (ROOT/'qa/build.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report))
